import random

import cocotb
from cocotb.clock import Clock
from cocotb.triggers import ClockCycles, FallingEdge, RisingEdge, Timer, with_timeout

CLK_NS = 10

FLAG_NAMES = (
    "inf",
    "snan",
    "qnan",
    "ine",
    "overflow",
    "underflow",
    "zero",
    "div_by_zero",
)

MAX_FINITE = (1 << 128) - (1 << 104)
MIN_NORMAL = 1 << 23


def decode(bits):
    sign = (bits >> 31) & 1
    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF

    if exponent == 0xFF:
        if fraction == 0:
            return ("inf", sign, 0, 1)
        if fraction & 0x400000:
            return ("qnan", sign, 0, 1)
        return ("snan", sign, 0, 1)

    if exponent == 0:
        if fraction == 0:
            return ("zero", sign, 0, 1)
        significand = fraction
        power = -149
    else:
        significand = (1 << 23) | fraction
        power = exponent - 150

    if power >= 0:
        return ("finite", sign, significand << power, 1)
    return ("finite", sign, significand, 1 << (-power))


def floor_log2_ratio(numerator, denominator):
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << (-exponent)) < denominator:
        exponent -= 1
    return exponent


def rounded_integer(numerator, denominator, sign, mode):
    quotient, remainder = divmod(numerator, denominator)
    if remainder == 0:
        return quotient

    if mode == 0:
        twice = remainder << 1
        if twice > denominator or (twice == denominator and (quotient & 1)):
            return quotient + 1
    elif mode == 2 and sign == 0:
        return quotient + 1
    elif mode == 3 and sign == 1:
        return quotient + 1
    return quotient


def round_finite(signed_numerator, denominator, mode, zero_sign):
    if signed_numerator == 0:
        return zero_sign << 31

    sign = int(signed_numerator < 0)
    numerator = abs(signed_numerator)

    # Overflow is handled separately so the result can follow the requested
    # rounding mode at the top of the finite range.
    if numerator > (MAX_FINITE * denominator):
        if mode == 0:
            threshold = ((1 << 128) - (1 << 104) + (1 << 103)) * denominator
            to_infinity = numerator >= threshold
        else:
            to_infinity = (mode == 2 and sign == 0) or (mode == 3 and sign == 1)
        if to_infinity:
            return (sign << 31) | 0x7F800000
        return (sign << 31) | 0x7F7FFFFF

    exponent = floor_log2_ratio(numerator, denominator)

    if exponent < -126:
        unit_power = -149
        scaled_numerator = numerator << 149
        scaled_denominator = denominator
        significand = rounded_integer(
            scaled_numerator, scaled_denominator, sign, mode
        )
        if significand == 0:
            return sign << 31
        if significand >= (1 << 23):
            return (sign << 31) | 0x00800000
        return (sign << 31) | significand

    unit_power = exponent - 23
    if unit_power >= 0:
        scaled_numerator = numerator
        scaled_denominator = denominator << unit_power
    else:
        scaled_numerator = numerator << (-unit_power)
        scaled_denominator = denominator

    significand = rounded_integer(scaled_numerator, scaled_denominator, sign, mode)
    if significand >= (1 << 24):
        significand >>= 1
        exponent += 1

    if exponent > 127:
        # This can only occur at the overflow boundary.
        if mode == 0 or (mode == 2 and sign == 0) or (mode == 3 and sign == 1):
            return (sign << 31) | 0x7F800000
        return (sign << 31) | 0x7F7FFFFF

    return (
        (sign << 31)
        | ((exponent + 127) << 23)
        | (significand - (1 << 23))
    )


def finite_bits_to_ratio(bits):
    kind, sign, numerator, denominator = decode(bits)
    if kind == "zero":
        return 0, 1
    if kind != "finite":
        return None
    return (-numerator if sign else numerator), denominator


def same_as_exact(bits, exact_numerator, exact_denominator):
    rounded = finite_bits_to_ratio(bits)
    if rounded is None:
        return False
    rounded_numerator, rounded_denominator = rounded
    return (
        rounded_numerator * exact_denominator
        == exact_numerator * rounded_denominator
    )


def make_special_result(bits, flags, mask=None):
    result = {"out": bits, "out_mask": 0xFFFFFFFF}
    if mask is not None:
        result["out_mask"] = mask
    result.update(flags)
    return result


def model(op, mode, opa, opb):
    a_kind, a_sign, a_num, a_den = decode(opa)
    b_kind, b_sign, b_num, b_den = decode(opb)

    flags = {name: 0 for name in FLAG_NAMES}
    flags["snan"] = int(a_kind == "snan" or b_kind == "snan")

    if op >= 4:
        return None

    if a_kind == "inf" and b_kind == "inf":
        return None

    if a_kind in ("qnan", "snan") or b_kind in ("qnan", "snan"):
        flags["qnan"] = 1
        if (a_kind in ("qnan", "snan")) != (b_kind in ("qnan", "snan")):
            nan_sign = a_sign if a_kind in ("qnan", "snan") else b_sign
            bits = (nan_sign << 31) | 0x7FC00001
            return make_special_result(bits, flags)
        return make_special_result(0x7FC00001, flags, 0x7FFFFFFF)

    a_zero = a_kind == "zero"
    b_zero = b_kind == "zero"

    def signed_value(kind, sign, numerator, denominator):
        if kind == "zero":
            return 0, 1
        value = numerator
        if sign:
            value = -value
        return value, denominator

    if op == 0 or op == 1:
        effective_b_sign = b_sign ^ int(op == 1)

        if a_kind == "inf":
            result_sign = a_sign
            bits = (result_sign << 31) | 0x7F800000
            flags["inf"] = 1
            return make_special_result(bits, flags)
        if b_kind == "inf":
            result_sign = effective_b_sign
            bits = (result_sign << 31) | 0x7F800000
            flags["inf"] = 1
            return make_special_result(bits, flags)

        an, ad = signed_value(a_kind, a_sign, a_num, a_den)
        bn, bd = signed_value(b_kind, effective_b_sign, b_num, b_den)
        exact_numerator = an * bd + bn * ad
        exact_denominator = ad * bd

        if exact_numerator == 0:
            if a_zero and b_zero and a_sign == effective_b_sign:
                zero_sign = a_sign
            else:
                zero_sign = int(mode == 3)
        else:
            zero_sign = int(exact_numerator < 0)

    elif op == 2:
        if (a_kind == "inf" and b_zero) or (b_kind == "inf" and a_zero):
            flags["qnan"] = 1
            return make_special_result(0x7FC00001, flags, 0x7FFFFFFF)

        result_sign = a_sign ^ b_sign
        if a_kind == "inf" or b_kind == "inf":
            flags["inf"] = 1
            return make_special_result(
                (result_sign << 31) | 0x7F800000, flags
            )
        if a_zero or b_zero:
            flags["zero"] = 1
            return make_special_result(result_sign << 31, flags)

        exact_numerator = a_num * b_num
        exact_denominator = a_den * b_den
        if result_sign:
            exact_numerator = -exact_numerator
        zero_sign = result_sign

    else:
        if a_zero and b_zero:
            flags["qnan"] = 1
            return make_special_result(0x7FC00001, flags, 0x7FFFFFFF)

        result_sign = a_sign ^ b_sign
        if a_kind == "inf":
            flags["inf"] = 1
            return make_special_result(
                (result_sign << 31) | 0x7F800000, flags
            )
        if b_kind == "inf":
            flags["zero"] = 1
            return make_special_result(result_sign << 31, flags)
        if b_zero:
            flags["inf"] = 1
            flags["div_by_zero"] = int(a_kind == "finite" and not a_zero)
            return make_special_result(
                (result_sign << 31) | 0x7F800000, flags
            )
        if a_zero:
            flags["zero"] = 1
            return make_special_result(result_sign << 31, flags)

        exact_numerator = a_num * b_den
        exact_denominator = a_den * b_num
        if result_sign:
            exact_numerator = -exact_numerator
        zero_sign = result_sign

    result_bits = round_finite(
        exact_numerator, exact_denominator, mode, zero_sign
    )

    magnitude_numerator = abs(exact_numerator)
    overflow = magnitude_numerator > MAX_FINITE * exact_denominator
    flags["overflow"] = int(overflow)
    flags["ine"] = int(
        overflow
        or not same_as_exact(result_bits, exact_numerator, exact_denominator)
    )

    if (result_bits & 0x7FFFFFFF) == 0:
        flags["zero"] = 1
    elif (result_bits & 0x7F800000) == 0x7F800000:
        flags["inf"] = 1

    tiny = (
        exact_numerator != 0
        and magnitude_numerator < (1 << 23) * exact_denominator
    )
    flags["underflow"] = int(tiny and flags["ine"])

    result = make_special_result(result_bits, flags)

    if op in (2, 3):
        nonzero_finite_inputs = (
            a_kind == "finite"
            and b_kind == "finite"
            and not a_zero
            and not b_zero
        )
        tiny_deviation = (
            nonzero_finite_inputs
            and magnitude_numerator <= (1 << 23) * exact_denominator
        )
        if tiny_deviation:
            result["out"] = None
            result["zero"] = None
            result["underflow"] = None

    if op == 3 and a_kind == "finite" and a_num < (1 << 23):
        result["ine"] = None
        result["underflow"] = None

    return result


async def start(dut):
    cocotb.start_soon(Clock(dut.clk, CLK_NS, "ns").start())
    dut.rmode.value = 0
    dut.fpu_op.value = 0
    dut.opa.value = 0
    dut.opb.value = 0
    await FallingEdge(dut.clk)


def check_result(dut, expected, label):
    if expected is None:
        return

    actual_out = int(dut.out.value)
    out_mask = expected["out_mask"]
    if expected["out"] is not None:
        assert (actual_out & out_mask) == (expected["out"] & out_mask), (
            f"{label}: out expected 0x{expected['out']:08x}, "
            f"got 0x{actual_out:08x}"
        )

    for name in FLAG_NAMES:
        wanted = expected[name]
        if wanted is None:
            continue
        actual = int(dut[name].value)
        assert actual == wanted, (
            f"{label}: {name} expected {wanted}, got {actual}"
        )


