    ]

    transactions = []
    for mode in range(4):
        for op in range(4):
            for index, a in enumerate(values):
                b = values[(index * 7 + op * 3 + 1) % len(values)]
                transactions.append((op, mode, a, b))

    # Exercise directed-rounding boundaries and exceptional cases in both
