    pairs = [
        (0x3F800000, 0x33800000),
        (0x3F800001, 0x33800000),
        (0x3F800000, 0xBF800000),
        (0x00800000, 0x00000001),
        (0x7F7FFFFF, 0x7F7FFFFF),
        (0x3F800000, 0x00000000),
        (0x00000001, 0x3F800000),
        (0x7F800000, 0x00000000),
        (0x00000000, 0x7F800000),
        (0x00000000, 0x00000000),
        (0x7FC12345, 0x3F800000),
        (0x3F800000, 0xFF800001),
        (0x7F800000, 0x3F800000),
        (0x3F800000, 0x7F800000),
        (0x3F800000, 0x3F000000),
        (0xBF800000, 0x40400000),
    ]
    for mode in range(4):
        for op in range(4):
            for a, b in pairs:
                transactions.append((op, mode, a, b))
                transactions.append((op, mode, b, a))

    random.seed(1337)
    for _ in range(1200):
        op = random.randrange(4)
        mode = random.randrange(4)
        if random.randrange(3) == 0:
            a = random.choice(values)
            b = random.choice(values)
        else:
            a = random.getrandbits(32)
            b = random.getrandbits(32)
        transactions.append((op, mode, a, b))

    async def run_transactions():
        pending = []
        for cycle, (op, mode, a, b) in enumerate(transactions):
            dut.fpu_op.value = op
            dut.rmode.value = mode
            dut.opa.value = a
            dut.opb.value = b
            pending.append(model(op, mode, a, b))

            await RisingEdge(dut.clk)
            await Timer(1, unit="ns")

            if len(pending) >= 4:
                check_result(
                    dut,
                    pending[-4],
                    f"cycle {cycle}, op={op}, mode={mode}, "
                    f"opa=0x{a:08x}, opb=0x{b:08x}",
                )

            await FallingEdge(dut.clk)

        for flush_index in range(3):
            dut.fpu_op.value = 0
            dut.rmode.value = 0
            dut.opa.value = 0
            dut.opb.value = 0
            pending.append(model(0, 0, 0, 0))

            await RisingEdge(dut.clk)
            await Timer(1, unit="ns")
            if len(pending) >= 4:
                check_result(
                    dut,
                    pending[-4],
                    f"flush cycle {flush_index}",
                )
            await FallingEdge(dut.clk)

    await with_timeout(run_transactions(), 100000, "ns")
