def classify(bits):
    sign = (bits >> 31) & 1
    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF

    if exponent == 0xFF:
        if fraction == 0:
            kind = "inf"
        elif fraction & 0x400000:
            kind = "qnan"
        else:
            kind = "snan"
    elif exponent == 0:
        kind = "zero" if fraction == 0 else "finite"
    else:
        kind = "finite"

    return sign, exponent, fraction, kind


