    """Return the exact finite value as a signed numerator and denominator."""
    sign, exponent, fraction, kind = classify(bits)
    if kind == "zero":
        return 0, 1

    if exponent == 0:
        significand = fraction
        power = -149
    else:
        significand = (1 << 23) | fraction
        power = exponent - 127 - 23

    numerator = significand
    denominator = 1
    if power >= 0:
        numerator <<= power
    else:
        denominator <<= -power

    if sign:
        numerator = -numerator
    return numerator, denominator


def compare_ratio_to_power(numerator, denominator, power):
    """Compare positive numerator/denominator with 2**power."""
    if power >= 0:
        right = denominator << power
        return (numerator > right) - (numerator < right)
    left = numerator << -power
    return (left > denominator) - (left < denominator)


