    """Round numerator/denominator * 2**shift to an integer."""
    if shift >= 0:
        numerator <<= shift
    else:
        denominator <<= -shift

    quotient, remainder = divmod(numerator, denominator)
    increment = False

    if remainder:
        if mode == 0:
            doubled = remainder << 1
            increment = doubled > denominator or (
                doubled == denominator and (quotient & 1) == 1
            )
        elif mode == 2:
            increment = sign == 0
        elif mode == 3:
            increment = sign == 1

    if increment:
        quotient += 1

    return quotient, remainder != 0


def round_finite(numerator, denominator, mode):
    """
    Return (result_bits, inexact, overflow, tiny).

    numerator/denominator is an exact signed rational.
    """
    if numerator == 0:
        return 0, False, False, False

    sign = 1 if numerator < 0 else 0
    magnitude = abs(numerator)
