        if (inf_a and zero_b) or (zero_a and inf_b):
            return special_result(0x7FC00001, snan, True)
        if inf_a or inf_b:
            return special_result(
                (result_sign << 31) | 0x7F800000, snan, False
            )
        if zero_a or zero_b:
            return special_result(result_sign << 31, snan, False)

        num_a, den_a = finite_ratio(opa)
        num_b, den_b = finite_ratio(opb)
        numerator = num_a * num_b
        denominator = den_a * den_b

    elif op == 3:
        result_sign = sign_a ^ sign_b

        if zero_a and zero_b:
            return special_result(0x7FC00001, snan, True)
        if inf_a:
            return special_result(
                (result_sign << 31) | 0x7F800000, snan, False
            )
        if inf_b:
            return special_result(result_sign << 31, snan, False)
        if zero_b:
            # zero_a was handled above, so opa is finite and nonzero.
            return special_result(
                (result_sign << 31) | 0x7F800000,
                snan,
                False,
                div_by_zero=True,
            )
        if zero_a:
            return special_result(result_sign << 31, snan, False)

        num_a, den_a = finite_ratio(opa)
        num_b, den_b = finite_ratio(opb)
