    return {
        "bits": result_bits,
        "flags": {
            "inf": int(is_inf),
            "snan": int(snan),
            "qnan": 0,
            "ine": int(inexact or overflow),
            "overflow": int(overflow),
            "underflow": int(underflow),
            "zero": int(is_zero),
            "div_by_zero": 0,
        },
        "check_sign": True,
        "tiny_mul_div": is_tiny_mul_div,
        "ine_unspecified": op == 3 and classify(opa)[1] == 0
