    values = [
        0x00000000, 0x80000000,
        0x00000001, 0x00000002, 0x00000003, 0x007FFFFF,
        0x00800000, 0x00800001, 0x00800002,
        0x3F000000, 0x3F000001, 0x3F7FFFFF, 0x3F800000,
        0x3F800001, 0x3FC00000, 0x40000000, 0x40400000,
        0x40700000, 0x40A00000, 0x41200000,
        0x4B000000, 0x4F000000,
        0x7F000000, 0x7F7FFFFE, 0x7F7FFFFF,
        0x80000001, 0x807FFFFF, 0x80800000,
        0xBF000000, 0xBF800000, 0xC0000000, 0xC0400000,
        0xFF000000, 0xFF7FFFFF,
        0x7F800000, 0xFF800000,
        0x7FC00000, 0x7FC12345, 0xFFC23456,
        0x7F800001, 0xFF800123,
    ]

    vectors = []
    for a in values:
        for b in values:
            for op in range(4):
                for mode in range(4):
                    vectors.append((op, mode, a, b, reference(op, mode, a, b)))

    rng = Random(0xF0A123)
    finite_values = []
    while len(finite_values) < 180:
        bits = rng.getrandbits(32)
        if classify(bits)[3] == "finite":
