    for _ in range(1000):
        a = rng.choice(values + finite_values)
        b = rng.choice(values + finite_values)
        op = rng.randrange(4)
        mode = rng.randrange(4)
        vectors.append((op, mode, a, b, reference(op, mode, a, b)))

