import random

import cocotb
from cocotb.clock import Clock
from cocotb.triggers import FallingEdge, Timer, RisingEdge, with_timeout


CLK_NS = 10
MASK32 = 0xFFFFFFFF
MAX_FINITE = 0x7F7FFFFF
MIN_NORMAL_MAG = 0x00800000


def fields(bits):
    sign = (bits >> 31) & 1
    exp = (bits >> 23) & 0xFF
    frac = bits & 0x7FFFFF
    return sign, exp, frac


def is_zero(bits):
    return (bits & 0x7FFFFFFF) == 0


def is_inf(bits):
    return (bits & 0x7FFFFFFF) == 0x7F800000


def is_nan(bits):
    sign, exp, frac = fields(bits)
    return exp == 0xFF and frac != 0


def is_snan(bits):
    sign, exp, frac = fields(bits)
    return exp == 0xFF and frac != 0 and (frac & 0x400000) == 0


def finite_parts(bits):
    """Return signed integer significand and power of two for a finite value."""
    sign, exp, frac = fields(bits)
    if exp == 0:
        significand = frac
        power = -149
    else:
        significand = (1 << 23) | frac
        power = exp - 150
    if sign:
        significand = -significand
    return significand, power


def as_ratio(significand, power):
    if power >= 0:
        return significand << power, 1
    return significand, 1 << (-power)


def floor_log2_ratio(numerator, denominator):
    """floor(log2(numerator / denominator)), for positive inputs."""
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << (-exponent)) < denominator:
        exponent -= 1
    return exponent


def rounded_integer(numerator, denominator, sign, mode):
    """Round a nonnegative ratio to an integer using the selected FPU mode."""
    quotient, remainder = divmod(numerator, denominator)
    if remainder == 0:
        return quotient

    if mode == 0:
        twice = remainder << 1
        if twice > denominator or (twice == denominator and (quotient & 1)):
            quotient += 1
    elif mode == 2 and sign == 0:
        quotient += 1
    elif mode == 3 and sign == 1:
        quotient += 1
    return quotient


def quantize_finite(numerator, denominator, sign, mode):
    """
    Quantize a nonzero exact rational to binary32.

    Returns (bits, inexact, overflow, unbounded_result_exceeds_max_finite).
    numerator and denominator are positive.
    """
    exponent = floor_log2_ratio(numerator, denominator)

    if exponent < -126:
        quantum_power = -149
    else:
        quantum_power = exponent - 23

    if quantum_power >= 0:
        scaled_num = numerator
        scaled_den = denominator << quantum_power
    else:
        scaled_num = numerator << (-quantum_power)
        scaled_den = denominator

    rounded = rounded_integer(scaled_num, scaled_den, sign, mode)
    inexact = (scaled_num % scaled_den) != 0

    if exponent < -126:
        if rounded == 0:
            bits = sign << 31
        elif rounded >= (1 << 23):
            bits = (sign << 31) | MIN_NORMAL_MAG
        else:
            bits = (sign << 31) | rounded
        exceeds_max = False
        return bits, inexact, False, exceeds_max

    if rounded >= (1 << 24):
        rounded >>= 1
        exponent += 1

    exceeds_max = exponent > 127
    if exponent > 127:
        to_infinity = (mode == 0) or (mode == 2 and sign == 0) or (
            mode == 3 and sign == 1
        )
        if to_infinity:
            bits = (sign << 31) | 0x7F800000
        else:
            bits = (sign << 31) | MAX_FINITE
        return bits, True, True, True

    exp_field = exponent + 127
    frac = rounded - (1 << 23)
    bits = (sign << 31) | (exp_field << 23) | frac
    return bits, inexact, False, exceeds_max


def exact_operation(op, a, b):
    """Return an exact signed ratio (numerator, positive denominator)."""
    sa, pa = finite_parts(a)
    sb, pb = finite_parts(b)

    if op == 0 or op == 1:
        if op == 1:
            sb = -sb
        common_power = min(pa, pb)
        total = (sa << (pa - common_power)) + (sb << (pb - common_power))
        return as_ratio(total, common_power)

    if op == 2:
        return as_ratio(sa * sb, pa + pb)

    # Division; the caller handles a zero denominator.
    numerator, denominator = as_ratio(sa, pa)
    other_num, other_den = as_ratio(sb, pb)
    result_num = numerator * other_den
    result_den = denominator * other_num
    if result_den < 0:
        result_num = -result_num
        result_den = -result_den
    return result_num, result_den


def zero_result(sign, flags):
    bits = sign << 31
    result = {"out": bits}
    result.update(flags)
    result["inf"] = 0
    result["qnan"] = 0
    result["zero"] = 1
    return result


def nan_result(a, b, flags, invalid=False):
    if not invalid and is_nan(a) != is_nan(b):
        nan_sign = fields(a if is_nan(a) else b)[0]
        bits = (nan_sign << 31) | 0x7FC00001
        check_sign = True
    else:
        bits = 0x7FC00001
        check_sign = False

    result = {"out": bits, "check_nan_sign": check_sign}
    result.update(flags)
    result["inf"] = 0
    result["qnan"] = 1
    result["zero"] = 0
    result["ine"] = 0
    result["overflow"] = 0
    result["underflow"] = 0
    result["div_by_zero"] = 0
    return result


def oracle(op, mode, a, b):
    snan = int(is_snan(a) or is_snan(b))
    flags = {"snan": snan}

    # The specification leaves all outputs unspecified for two infinities.
    if is_inf(a) and is_inf(b):
        return None

    if is_nan(a) or is_nan(b):
        return nan_result(a, b, flags)

    za = is_zero(a)
    zb = is_zero(b)
    ia = is_inf(a)
    ib = is_inf(b)

    if op == 2 and ((ia and zb) or (ib and za)):
        return nan_result(a, b, flags, invalid=True)

    if op == 3 and za and zb:
        return nan_result(a, b, flags, invalid=True)

    if op in (0, 1):
        sign_b = fields(b)[0] ^ (1 if op == 1 else 0)
        if ia or ib:
            if ia:
                sign = fields(a)[0]
            else:
                sign = sign_b
            return {
                "out": (sign << 31) | 0x7F800000,
                "inf": 1, "snan": snan, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            }
    elif op == 2:
        sign = fields(a)[0] ^ fields(b)[0]
        if ia or ib:
            return {
                "out": (sign << 31) | 0x7F800000,
                "inf": 1, "snan": snan, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            }
    else:
        sign = fields(a)[0] ^ fields(b)[0]
        if ib:
            return zero_result(sign, {
                "snan": snan, "ine": 0, "overflow": 0,
                "underflow": 0, "div_by_zero": 0,
            })
        if ia:
            return {
                "out": (sign << 31) | 0x7F800000,
                "inf": 1, "snan": snan, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 0,
            }
        if zb and not za:
            return {
                "out": (sign << 31) | 0x7F800000,
                "inf": 1, "snan": snan, "qnan": 0, "ine": 0,
                "overflow": 0, "underflow": 0, "zero": 0,
                "div_by_zero": 1,
            }

    if op == 2 and (ia or ib):
        sign = fields(a)[0] ^ fields(b)[0]
        return {
            "out": (sign << 31) | 0x7F800000,
            "inf": 1, "snan": snan, "qnan": 0, "ine": 0,
            "overflow": 0, "underflow": 0, "zero": 0,
            "div_by_zero": 0,
        }

    if za or zb:
        if op == 2 or op == 3:
            sign = fields(a)[0] ^ fields(b)[0]
            return zero_result(sign, {
                "snan": snan, "ine": 0, "overflow": 0,
                "underflow": 0, "div_by_zero": 0,
            })

        # For add/sub, determine the effective signs of zero operands and
        # apply IEEE's exact-zero sign rule.
        sign_a = fields(a)[0]
        sign_b = fields(b)[0] ^ (1 if op == 1 else 0)
        if za and zb and sign_a == sign_b:
            sign = sign_a
        else:
            sign = int(mode == 3)
        return zero_result(sign, {
            "snan": snan, "ine": 0, "overflow": 0,
            "underflow": 0, "div_by_zero": 0,
        })

    numerator, denominator = exact_operation(op, a, b)
    if numerator == 0:
        sign = int(mode == 3)
        return zero_result(sign, {
            "snan": snan, "ine": 0, "overflow": 0,
            "underflow": 0, "div_by_zero": 0,
        })

    sign = int(numerator < 0)
    magnitude = abs(numerator)
    out, inexact, overflow, exceeds_max = quantize_finite(
        magnitude, denominator, sign, mode
    )

    result = {
        "out": out,
        "inf": int(is_inf(out)),
        "snan": snan,
        "qnan": 0,
        "ine": int(inexact or overflow),
        "overflow": int(overflow or exceeds_max),
        "underflow": 0,
        "zero": int(is_zero(out)),
        "div_by_zero": 0,
    }

    # Underflow is based on tininess before rounding.
    if magnitude < (denominator << 0):
        pass
    tiny = (magnitude << 126) < denominator
    result["underflow"] = int(tiny and inexact)

    # Division with a subnormal numerator has unspecified ine and underflow.
    if op == 3 and fields(a)[1] == 0 and fields(a)[2] != 0:
        result["ine"] = None
        result["underflow"] = None

    # The design documents non-IEEE output/zero/underflow behavior for tiny
    # multiply and divide results. Keep the other flags checked.
    if op in (2, 3):
        rounded_mag = out & 0x7FFFFFFF
        tiny_case = (
            (magnitude << 126) <= denominator
            or is_zero(out)
            or (rounded_mag < MIN_NORMAL_MAG)
            or rounded_mag == MIN_NORMAL_MAG
        )
        if tiny_case:
            result["out_unspecified"] = True
            result["zero"] = None
            result["underflow"] = None

    return result


def make_vectors():
    vectors = []
    modes = (0, 1, 2, 3)

    directed = [
        0x00000000, 0x80000000, 0x00000001, 0x00000002,
        0x007FFFFF, 0x00800000, 0x00800001,
        0x3F800000, 0x3F800001, 0x3F000000, 0x40000000,
        0x40400000, 0xBF800000, 0xC0000000, 0x7F7FFFFF,
        0xFF7FFFFF, 0x7F800000, 0xFF800000,
        0x7FC12345, 0xFFC54321, 0x7F800001, 0xFF800001,
    ]

    # Exercise every operation and rounding mode across common exact,
    # inexact, signed-zero, subnormal, infinity, and NaN cases.
    for op in range(4):
        for mode in modes:
            for i, a in enumerate(directed):
                b = directed[(i * 7 + mode * 3 + op) % len(directed)]
                vectors.append((op, mode, a, b))

    explicit_pairs = [
        (0x3F800000, 0x33800000),  # halfway addition
        (0x3F800000, 0x34000000),
        (0x3F800000, 0x3F800000),
        (0x3F800000, 0xBF800000),
        (0x00000001, 0x00000001),
        (0x00800000, 0x3F000000),
        (0x7F7FFFFF, 0x40000000),
        (0x3F800000, 0x40400000),
        (0x40000000, 0x40400000),
        (0x3F800000, 0x00000000),
        (0x00000000, 0x3F800000),
        (0x7F800000, 0x00000000),
        (0x00000000, 0x7F800000),
        (0x7F800000, 0x3F800000),
        (0x3F800000, 0x7F800000),
        (0x7FC00001, 0x3F800000),
        (0x3F800000, 0xFF800001),
    ]
    for op in range(4):
        for mode in modes:
            for a, b in explicit_pairs:
                vectors.append((op, mode, a, b))

    rng = random.Random(0xF012345)
    for _ in range(700):
        op = rng.randrange(4)
        mode = rng.randrange(4)
        a = rng.getrandbits(32)
        b = rng.getrandbits(32)
        vectors.append((op, mode, a, b))

    return vectors


async def drive_and_check(dut, vectors):
    dut.rmode.value = 0
    dut.fpu_op.value = 0
    dut.opa.value = 0
    dut.opb.value = 0
    cocotb.start_soon(Clock(dut.clk, CLK_NS, "ns").start())

    stream = list(vectors)
    stream.extend([(0, 0, 0x3F800000, 0x3F800000)] * 3)

    for edge_index, item in enumerate(stream):
        await with_timeout(FallingEdge(dut.clk), 100, "ns")
        op, mode, a, b = item
        dut.fpu_op.value = op
        dut.rmode.value = mode
        dut.opa.value = a
        dut.opb.value = b

        await with_timeout(RisingEdge(dut.clk), 100, "ns")
        await Timer(1, "ns")

        result_index = edge_index - 3
        if result_index < 0 or result_index >= len(vectors):
            continue

        expected = oracle(*vectors[result_index])
        if expected is None:
            continue

        observed = {
            "out": int(dut.out.value),
            "inf": int(dut.inf.value),
            "snan": int(dut.snan.value),
            "qnan": int(dut.qnan.value),
            "ine": int(dut.ine.value),
            "overflow": int(dut.overflow.value),
            "underflow": int(dut.underflow.value),
            "zero": int(dut.zero.value),
            "div_by_zero": int(dut.div_by_zero.value),
        }

        label = "edge {} input {}".format(edge_index, vectors[result_index])
        if expected.get("out_unspecified", False):
            for name in (
                "inf", "snan", "qnan", "ine", "overflow", "div_by_zero"
            ):
