                    label, expected["out"], observed["out"]
                )
            )
        else:
            assert (observed["out"] & 0x7FFFFFFF) == 0x7FC00001, (
                "{}: NaN magnitude expected 0x7fc00001, got 0x{:08x}".format(
                    label, observed["out"]
                )
            )

        for name in (
            "inf", "snan", "qnan", "ine", "overflow", "underflow",
            "zero", "div_by_zero",
        ):
            wanted = expected[name]
            if wanted is not None:
                assert observed[name] == wanted, (
                    "{}: {} expected {}, got {}".format(
                        label, name, wanted, observed[name]
                    )
                )


@cocotb.test()
async def fpu_behavior(dut):
