from cocotb.triggers import FallingEdge, RisingEdge, Timer


CLK_NS = 10
MASK32 = 0xFFFFFFFF
MAX_FINITE = 0x7F7FFFFF
MIN_NORMAL_EXP = -126


def decode(bits):
    sign = (bits >> 31) & 1
    exp = (bits >> 23) & 0xFF
    frac = bits & 0x7FFFFF

    if exp == 0xFF:
        if frac == 0:
            return ("inf", 0, 0, sign, False)
        return ("nan", 0, 0, sign, (frac & 0x400000) == 0)
    if exp == 0:
        if frac == 0:
            return ("zero", 0, 0, sign, False)
        return ("finite", frac, -149, sign, False)
    return ("finite", (1 << 23) | frac, exp - 150, sign, False)


def compare_value_to_power(n, d, exponent, power):
    shift = exponent - power
    if shift >= 0:
        left = n << shift
        right = d
    else:
        left = n
        right = d << (-shift)
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def floor_log2_ratio(n, d, exponent):
    result = n.bit_length() - d.bit_length() + exponent
    while compare_value_to_power(n, d, exponent, result) < 0:
        result -= 1
    while compare_value_to_power(n, d, exponent, result + 1) >= 0:
        result += 1
    return result


def rounded_integer(n, d, shift, sign, mode):
    if shift >= 0:
        numerator = n << shift
        denominator = d
    else:
        numerator = n
        denominator = d << (-shift)

    q, rem = divmod(numerator, denominator)
    if rem == 0:
        return q, False

    increment = False
    if mode == 0:
        twice = rem << 1
        increment = twice > denominator or (twice == denominator and (q & 1) != 0)
    elif mode == 2:
        increment = sign == 0
    elif mode == 3:
        increment = sign == 1

    if increment:
        q += 1
    return q, True


def round_finite(n, d, exponent, sign, mode):
    """Return (result bits, inexact, overflow) for a nonnegative exact n/d*2**exponent."""
    if n == 0:
        return sign << 31, False, False

    top = floor_log2_ratio(n, d, exponent)
    quantum = -149 if top < MIN_NORMAL_EXP else top - 23
    q, inexact = rounded_integer(n, d, exponent - quantum, sign, mode)

    rounded_top = top
    if top < MIN_NORMAL_EXP:
        # Subnormal encodings and the smallest normal share this integer scale.
        if q >= (1 << 23):
            magnitude = 1 << 23
        else:
            magnitude = q
    else:
        if q >= (1 << 24):
            q >>= 1
            rounded_top += 1

        if rounded_top > 127:
            overflow = True
            goes_to_infinity = mode == 0 or (mode == 2 and sign == 0) or (
                mode == 3 and sign == 1
            )
            magnitude = 0x7F800000 if goes_to_infinity else MAX_FINITE
            return (sign << 31) | magnitude, True, overflow

        exp_field = rounded_top + 127
        frac_field = q - (1 << 23)
        magnitude = (exp_field << 23) | (frac_field & 0x7FFFFF)

