from random import Random

import cocotb
from cocotb.clock import Clock
from cocotb.triggers import FallingEdge, RisingEdge, Timer


CLK_NS = 10
MASK32 = 0xFFFFFFFF
MAX_FINITE = 0x7F7FFFFF
MIN_NORMAL_EXP = -126


def decode(bits):
    sign = (bits >> 31) & 1
    exp = (bits >> 23) & 0xFF
    frac = bits & 0x7FFFFF

    if exp == 0xFF:
        if frac == 0:
            return ("inf", 0, 0, sign, False)
        return ("nan", 0, 0, sign, (frac & 0x400000) == 0)
    if exp == 0:
        if frac == 0:
            return ("zero", 0, 0, sign, False)
        return ("finite", frac, -149, sign, False)
    return ("finite", (1 << 23) | frac, exp - 150, sign, False)


def compare_value_to_power(n, d, exponent, power):
    shift = exponent - power
    if shift >= 0:
        left = n << shift
        right = d
    else:
        left = n
        right = d << (-shift)
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def floor_log2_ratio(n, d, exponent):
    result = n.bit_length() - d.bit_length() + exponent
    while compare_value_to_power(n, d, exponent, result) < 0:
        result -= 1
    while compare_value_to_power(n, d, exponent, result + 1) >= 0:
        result += 1
    return result


def rounded_integer(n, d, shift, sign, mode):
    if shift >= 0:
        numerator = n << shift
        denominator = d
    else:
        numerator = n
        denominator = d << (-shift)

    q, rem = divmod(numerator, denominator)
    if rem == 0:
        return q, False

    increment = False
    if mode == 0:
        twice = rem << 1
        increment = twice > denominator or (twice == denominator and (q & 1) != 0)
    elif mode == 2:
        increment = sign == 0
    elif mode == 3:
        increment = sign == 1

    if increment:
        q += 1
    return q, True


def round_finite(n, d, exponent, sign, mode):
    """Return (result bits, inexact, overflow) for a nonnegative exact n/d*2**exponent."""
    if n == 0:
        return sign << 31, False, False

    top = floor_log2_ratio(n, d, exponent)
    quantum = -149 if top < MIN_NORMAL_EXP else top - 23
    q, inexact = rounded_integer(n, d, exponent - quantum, sign, mode)

    rounded_top = top
    if top < MIN_NORMAL_EXP:
        # Subnormal encodings and the smallest normal share this integer scale.
        if q >= (1 << 23):
            magnitude = 1 << 23
        else:
            magnitude = q
    else:
        if q >= (1 << 24):
            q >>= 1
            rounded_top += 1

        if rounded_top > 127:
            overflow = True
            goes_to_infinity = mode == 0 or (mode == 2 and sign == 0) or (
                mode == 3 and sign == 1
            )
            magnitude = 0x7F800000 if goes_to_infinity else MAX_FINITE
            return (sign << 31) | magnitude, True, overflow

        exp_field = rounded_top + 127
        frac_field = q - (1 << 23)
        magnitude = (exp_field << 23) | (frac_field & 0x7FFFFF)

    return (sign << 31) | magnitude, inexact, False


def nan_result(sign=None):
    if sign is None:
        out = 0x7FC00001
        out_mask = 0x7FFFFFFF
    else:
        out = (sign << 31) | 0x7FC00001
        out_mask = MASK32
    return {
        "out": out,
        "out_mask": out_mask,
        "inf": 0,
        "snan": None,
        "qnan": 1,
        "ine": 0,
        "overflow": 0,
        "underflow": 0,
        "zero": 0,
        "div_by_zero": 0,
    }


def reference(op, mode, opa, opb):
    a = decode(opa)
    b = decode(opb)
    ak, asig, ae, asign, asnan = a
    bk, bsig, be, bsign, bsnan = b

    # The specification leaves the entire result unspecified for two infinities.
    if ak == "inf" and bk == "inf":
        return None

    snan_flag = int(asnan or bsnan)

    if ak == "nan" or bk == "nan":
        if ak == "nan" and bk != "nan":
            result = nan_result(asign)
        elif bk == "nan" and ak != "nan":
            result = nan_result(bsign)
        else:
            result = nan_result()
        result["snan"] = snan_flag
        return result

    def special_infinity(sign):
        return {
            "out": (sign << 31) | 0x7F800000,
            "out_mask": MASK32,
            "inf": 1,
            "snan": snan_flag,
            "qnan": 0,
            "ine": 0,
            "overflow": 0,
            "underflow": 0,
            "zero": 0,
            "div_by_zero": 0,
        }

    def special_zero(sign):
        return {
            "out": sign << 31,
            "out_mask": MASK32,
            "inf": 0,
            "snan": snan_flag,
            "qnan": 0,
            "ine": 0,
            "overflow": 0,
            "underflow": 0,
            "zero": 1,
            "div_by_zero": 0,
        }

    if op == 0 or op == 1:
        b_effective_sign = bsign ^ int(op == 1)
        if ak == "inf":
            return special_infinity(asign)
        if bk == "inf":
            return special_infinity(b_effective_sign)

        common_exp = min(ae, be)
        left = (asig << (ae - common_exp)) * (-1 if asign else 1)
        right = (bsig << (be - common_exp)) * (
            -1 if b_effective_sign else 1
        )
        total = left + right
        if total == 0:
            # Same-sign negative zero operands retain -0. Other exact zero
            # sums use the rounding-mode rule.
            if asig == 0 and bsig == 0 and asign == 1 and b_effective_sign == 1:
                sign = 1
            else:
                sign = int(mode == 3)
            return special_zero(sign)
        sign = int(total < 0)
        n = abs(total)
        d = 1
        exponent = common_exp

    elif op == 2:
        sign = asign ^ bsign
        if (ak == "inf" and bk == "zero") or (bk == "inf" and ak == "zero"):
            result = nan_result()
            result["snan"] = snan_flag
            return result
        if ak == "inf" or bk == "inf":
            return special_infinity(sign)
        if ak == "zero" or bk == "zero":
            return special_zero(sign)
        n = asig * bsig
        d = 1
        exponent = ae + be

    elif op == 3:
        sign = asign ^ bsign
        if ak == "inf":
            return special_infinity(sign)
        if bk == "inf":
            return special_zero(sign)
        if ak == "zero" and bk == "zero":
            result = nan_result()
            result["snan"] = snan_flag
            return result
        if bk == "zero":
            result = special_infinity(sign)
            result["div_by_zero"] = 1
            return result
        if ak == "zero":
            return special_zero(sign)
        n = asig
        d = bsig
        exponent = ae - be

    else:
        return None

    if n == 0:
        return special_zero(sign)

    exact_top = floor_log2_ratio(n, d, exponent)
    tiny = exact_top < MIN_NORMAL_EXP
    out, inexact, overflow = round_finite(n, d, exponent, sign, mode)

    result = {
        "out": out,
        "out_mask": MASK32,
        "inf": int((out & 0x7FFFFFFF) == 0x7F800000),
        "snan": snan_flag,
        "qnan": 0,
        "ine": int(inexact or overflow),
        "overflow": int(overflow),
        "underflow": int(tiny and inexact),
        "zero": int((out & 0x7FFFFFFF) == 0),
        "div_by_zero": 0,
