    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF

    if exponent == 0xFF:
        if fraction == 0:
            return ("inf", sign, 0, 1)
        return ("nan", sign, 0, 1)

    if exponent == 0:
        return ("finite", sign, fraction, 1 << 149)

    significand = (1 << 23) | fraction
    power = exponent - 127 - 23
    if power >= 0:
        return ("finite", sign, significand << power, 1)
    return ("finite", sign, significand, 1 << (-power))


def as_signed_ratio(value):
    kind, sign, numerator, denominator = value
    if sign:
        numerator = -numerator
    return numerator, denominator


def floor_log2_ratio(numerator, denominator):
    estimate = numerator.bit_length() - denominator.bit_length()
    if estimate >= 0:
        if numerator < (denominator << estimate):
            estimate -= 1
    elif (numerator << (-estimate)) < denominator:
        estimate -= 1
    return estimate


def rounded_bits(numerator, denominator, sign, mode):
    """Round a finite signed rational to binary32; return bits, inexact, overflow."""
    magnitude = abs(numerator)
    if magnitude == 0:
        return (sign << 31), False, False

    exponent = floor_log2_ratio(magnitude, denominator)
    unit = exponent - 23 if exponent >= -126 else -149

    if unit >= 0:
        scaled_num = magnitude
        scaled_den = denominator << unit
    else:
        scaled_num = magnitude << (-unit)
        scaled_den = denominator

    quotient, remainder = divmod(scaled_num, scaled_den)
    inexact = remainder != 0

    increment = False
    if mode == 0:
        doubled = remainder << 1
        increment = doubled > scaled_den or (
            doubled == scaled_den and (quotient & 1) == 1
        )
    elif mode == 2:
        increment = sign == 0 and inexact
    elif mode == 3:
        increment = sign == 1 and inexact

    if increment:
        quotient += 1

    if exponent < -126:
        if quotient >= (1 << 23):
            result = (sign << 31) | (1 << 23)
        else:
            result = (sign << 31) | quotient
        return result, inexact, False

    if quotient >= (1 << 24):
        quotient >>= 1
        unit += 1

    unbiased_exponent = unit + 23
    if unbiased_exponent > 127:
        away_from_zero = (mode == 2 and sign == 0) or (
            mode == 3 and sign == 1
        )
        if mode == 0 or away_from_zero:
            result = (sign << 31) | 0x7F800000
        else:
            result = (sign << 31) | 0x7F7FFFFF
        return result, True, True

    exponent_field = unbiased_exponent + 127
    fraction = quotient - (1 << 23)
    result = (sign << 31) | (exponent_field << 23) | fraction
    return result, inexact, False


