def _decode(bits):
    """Return (class, sign, fraction) for a binary32 bit pattern."""
    sign = (bits >> 31) & 1
    exp = (bits >> 23) & 0xFF
    frac = bits & 0x7FFFFF
    if exp == 0xFF:
        if frac == 0:
            return "inf", sign, frac
        if frac & 0x400000:
            return "qnan", sign, frac
        return "snan", sign, frac
    if exp == 0:
        if frac == 0:
            return "zero", sign, frac
        return "finite", sign, frac
    return "finite", sign, frac


def _finite_ratio(bits):
    """Return the exact signed value as numerator / positive denominator."""
    cls, sign, frac = _decode(bits)
    if cls == "zero":
        return 0, 1
    exp = (bits >> 23) & 0xFF
    if exp == 0:
        significand = frac
        shift = -149
    else:
        significand = 0x800000 | frac
        shift = exp - 127 - 23
    numerator = significand
    denominator = 1
    if shift >= 0:
        numerator <<= shift
    else:
        denominator <<= -shift
    if sign:
        numerator = -numerator
    return numerator, denominator


