    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << -exponent) < denominator:
        exponent -= 1
    return exponent


def _rounded_quotient(numerator, denominator, shift, sign, rmode):
    """Round (numerator / denominator) / 2**shift to an integer."""
    if shift >= 0:
        denominator <<= shift
    else:
        numerator <<= -shift

    quotient, remainder = divmod(numerator, denominator)
    if remainder == 0:
        return quotient, False

    increment = False
    if rmode == 0:
        twice = remainder << 1
        increment = twice > denominator or (
            twice == denominator and (quotient & 1) == 1
        )
    elif rmode == 2:
        increment = sign == 0
    elif rmode == 3:
        increment = sign == 1

    if increment:
        quotient += 1
    return quotient, True


def _round_finite(numerator, denominator, rmode):
    """Round an exact signed rational to binary32 and return flags."""
    if numerator == 0:
        return 0, False, False, False

    sign = int(numerator < 0)
    magnitude = abs(numerator)
    exponent = _floor_log2_ratio(magnitude, denominator)

    if exponent >= -126:
