from cocotb.clock import Clock
from cocotb.triggers import FallingEdge, RisingEdge, Timer, with_timeout

CLK_NS = 10


def classify(bits):
    sign = (bits >> 31) & 1
    exponent = (bits >> 23) & 0xFF
    fraction = bits & 0x7FFFFF

    if exponent == 0xFF:
        if fraction == 0:
            return ("inf", sign, 0, 0)
        if fraction & 0x400000:
            return ("qnan", sign, 0, 0)
        return ("snan", sign, 0, 0)

    if exponent == 0:
        if fraction == 0:
            return ("zero", sign, 0, 0)
        return ("finite", sign, fraction, -149)

    return ("finite", sign, (1 << 23) | fraction, exponent - 150)


def floor_log2_ratio(numerator, denominator):
    """floor(log2(numerator / denominator)), for positive integers."""
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    else:
        if (numerator << (-exponent)) < denominator:
            exponent -= 1
    return exponent


def ratio_in_units(numerator, denominator, binary_exponent, unit_exponent):
    shift = binary_exponent - unit_exponent
    if shift >= 0:
        return numerator << shift, denominator
    return numerator, denominator << (-shift)


def rounded_integer(numerator, denominator, binary_exponent, unit_exponent, sign, mode):
    scaled_num, scaled_den = ratio_in_units(
        numerator, denominator, binary_exponent, unit_exponent
    )
    quotient, remainder = divmod(scaled_num, scaled_den)

    if remainder:
        if mode == 0:
            twice_remainder = remainder << 1
            if twice_remainder > scaled_den or (
                twice_remainder == scaled_den and (quotient & 1)
            ):
                quotient += 1
        elif mode == 2 and sign == 0:
            quotient += 1
        elif mode == 3 and sign == 1:
            quotient += 1

    return quotient, remainder != 0


def overflow_result(sign, mode):
    goes_to_infinity = (
        mode == 0
        or (mode == 2 and sign == 0)
        or (mode == 3 and sign == 1)
    )
    if goes_to_infinity:
        return (sign << 31) | 0x7F800000
    return (sign << 31) | 0x7F7FFFFF


def round_finite(numerator, denominator, binary_exponent, mode):
    """Round an exact signed numerator/denominator times 2**binary_exponent."""
    sign = 1 if numerator < 0 else 0
    numerator = abs(numerator)

    if numerator == 0:
        return sign << 31, False, False

    exponent = floor_log2_ratio(numerator, denominator) + binary_exponent

    if exponent < -126:
        significand, inexact = rounded_integer(
            numerator, denominator, binary_exponent, -149, sign, mode
        )
        if significand == 0:
            return sign << 31, False, inexact
        if significand >= (1 << 23):
            return (sign << 31) | 0x00800000, False, inexact
        return (sign << 31) | significand, False, inexact

    significand, inexact = rounded_integer(
        numerator, denominator, binary_exponent, exponent - 23, sign, mode
    )

    if significand >= (1 << 24):
        significand >>= 1
        exponent += 1

    if exponent > 127:
        return overflow_result(sign, mode), True, True

    bits = (sign << 31) | ((exponent + 127) << 23) | (significand & 0x7FFFFF)
    return bits, False, inexact


def equals_power_of_two(numerator, denominator, binary_exponent, power):
    shift = binary_exponent - power
    if shift >= 0:
        return (numerator << shift) == denominator
    return numerator == (denominator << (-shift))


def model(vector):
