    if op >= 4:
        return None

    kind_a, sign_a, sig_a, exp_a = classify(opa)
    kind_b, sign_b, sig_b, exp_b = classify(opb)
    signaling = int(kind_a == "snan" or kind_b == "snan")

    # The specification leaves every output unspecified for two infinities.
    if kind_a == "inf" and kind_b == "inf":
        return None

    nan_a = kind_a in ("qnan", "snan")
    nan_b = kind_b in ("qnan", "snan")
    invalid = (
        op == 2
        and ((kind_a == "zero" and kind_b == "inf") or
             (kind_a == "inf" and kind_b == "zero"))
    ) or (
        op == 3 and kind_a == "zero" and kind_b == "zero"
    )

    if nan_a or nan_b or invalid:
        bits = 0x7FC00001
        if nan_a != nan_b:
            bits |= (sign_a if nan_a else sign_b) << 31
        flags = {
            "inf": 0,
            "snan": signaling,
            "qnan": 1,
            "ine": 0,
            "overflow": 0,
            "underflow": 0,
            "zero": 0,
            "div_by_zero": 0,
        }
