            bits = (sign_a ^ sign_b) << 31

        flags = {
            "inf": int((bits & 0x7FFFFFFF) == 0x7F800000),
            "snan": signaling,
            "qnan": 0,
            "ine": 0,
            "overflow": 0,
            "underflow": 0,
            "zero": int((bits & 0x7FFFFFFF) == 0),
            "div_by_zero": div_by_zero,
        }
        return bits, flags, False, False

