        effective_sign_b = sign_b ^ (1 if op == 1 else 0)
        common_exponent = min(exp_a, exp_b)
        term_a = sig_a << (exp_a - common_exponent)
        term_b = sig_b << (exp_b - common_exponent)
        signed_a = -term_a if sign_a else term_a
        signed_b = -term_b if effective_sign_b else term_b
        exact_numerator = signed_a + signed_b
        exact_denominator = 1
        exact_exponent = common_exponent

