            if sig_a == 0 and sig_b == 0 and sign_a == effective_sign_b:
                zero_sign = sign_a
            else:
                zero_sign = int(mode == 3)
            bits = zero_sign << 31
            flags = {
                "inf": 0,
                "snan": signaling,
                "qnan": 0,
                "ine": 0,
                "overflow": 0,
                "underflow": 0,
                "zero": 1,
                "div_by_zero": 0,
            }
            return bits, flags, False, False

    elif op == 2:
        exact_numerator = sig_a * sig_b
        if sign_a ^ sign_b:
            exact_numerator = -exact_numerator
        exact_denominator = 1
        exact_exponent = exp_a + exp_b

    else:
        exact_numerator = sig_a
        if sign_a ^ sign_b:
            exact_numerator = -exact_numerator
        exact_denominator = sig_b
        exact_exponent = exp_a - exp_b

    result_bits, overflow_flag, inexact = round_finite(
        exact_numerator, exact_denominator, exact_exponent, mode
    )

    magnitude_numerator = abs(exact_numerator)
    exact_zero = magnitude_numerator == 0
    tiny = False
    tiny_multiply_or_divide = False

    if not exact_zero:
        exact_exponent_floor = (
            floor_log2_ratio(magnitude_numerator, exact_denominator)
            + exact_exponent
        )
        tiny = exact_exponent_floor < -126

        if op in (2, 3):
            tiny_multiply_or_divide = tiny or equals_power_of_two(
                magnitude_numerator,
                exact_denominator,
                exact_exponent,
                -126,
            )

    underflow_flag = int(tiny and inexact and op in (2, 3))
    flags = {
        "inf": int((result_bits & 0x7FFFFFFF) == 0x7F800000),
        "snan": signaling,
        "qnan": 0,
        "ine": int(inexact or overflow_flag),
        "overflow": int(overflow_flag),
        "underflow": underflow_flag,
        "zero": int((result_bits & 0x7FFFFFFF) == 0),
        "div_by_zero": 0,
    }

    # For division with a subnormal numerator, ine is unspecified.
    skip_ine = op == 3 and kind_a == "finite" and exp_a == -149
    return result_bits, flags, tiny_multiply_or_divide, skip_ine


def make_vectors():
    values = [
        0x00000000, 0x80000000,
        0x00000001, 0x80000001,
        0x00000002, 0x80000002,
        0x003FFFFF, 0x007FFFFE, 0x007FFFFF,
        0x00800000, 0x80800000,
        0x00800001, 0x80800001,
        0x3EFFFFFF, 0x3F000000, 0x3F000001,
