        0x4B000000, 0x4B000001,
        0x7F7FFFFE, 0x7F7FFFFF,
        0xFF7FFFFE, 0xFF7FFFFF,
        0x7F800000, 0xFF800000,
        0x7FC00000, 0xFFC12345,
        0x7F800001, 0xFF800123,
    ]

