        "underflow": 0,
        "zero": 0,
        "div_by_zero": 0,
    }

    if a_kind == "nan" or b_kind == "nan":
        if a_kind == "nan" and b_kind == "nan":
            return (0x7FC00001, 0x7FFFFFFF, flags)
        nan_sign = a_sign if a_kind == "nan" else b_sign
        flags["qnan"] = 1
        return ((nan_sign << 31) | 0x7FC00001, 0xFFFFFFFF, flags)

    invalid = (
        (op == 2 and ((a_kind == "inf" and b_kind == "zero")
                      or (a_kind == "zero" and b_kind == "inf")))
        or (op == 3 and a_kind == "zero" and b_kind == "zero")
    )
    if invalid:
        flags["qnan"] = 1
        return (0x7FC00001, 0x7FFFFFFF, flags)

    if op in (0, 1):
        b_effective_sign = b_sign ^ (1 if op == 1 else 0)

        if a_kind == "inf":
            result_sign = a_sign
            result = (result_sign << 31) | 0x7F800000
            flags["inf"] = 1
            return (result, 0xFFFFFFFF, flags)

        if b_kind == "inf":
            result = (b_effective_sign << 31) | 0x7F800000
            flags["inf"] = 1
            return (result, 0xFFFFFFFF, flags)

        a_num, a_den = finite_fraction(opa)
        b_num, b_den = finite_fraction(opb)
        if op == 1:
            b_num = -b_num
        numerator = a_num * b_den + b_num * a_den
        denominator = a_den * b_den

        if numerator == 0:
            if a_kind == "zero" and b_kind == "zero" and a_sign == b_effective_sign:
                zero_sign = a_sign
            else:
                zero_sign = 1 if mode == 3 else 0
            result = zero_sign << 31
            flags["zero"] = 1
            return (result, 0xFFFFFFFF, flags)

        result, overflow, inexact, underflow = round_finite(
            numerator, denominator, mode
        )
        flags["overflow"] = overflow
        flags["ine"] = inexact
        flags["underflow"] = underflow
        flags["inf"] = int((result & 0x7FFFFFFF) == 0x7F800000)
        flags["zero"] = int((result & 0x7FFFFFFF) == 0)
        return (result, 0xFFFFFFFF, flags)

    result_sign = a_sign ^ b_sign

    if op == 2:
        if a_kind == "inf" or b_kind == "inf":
            result = (result_sign << 31) | 0x7F800000
            flags["inf"] = 1
            return (result, 0xFFFFFFFF, flags)

        if a_kind == "zero" or b_kind == "zero":
            result = result_sign << 31
            flags["zero"] = 1
            return (result, 0xFFFFFFFF, flags)

        a_num, a_den = finite_fraction(opa)
        b_num, b_den = finite_fraction(opb)
        numerator = a_num * b_num
        denominator = a_den * b_den

    else:
        if a_kind == "inf":
            result = (result_sign << 31) | 0x7F800000
            flags["inf"] = 1
            return (result, 0xFFFFFFFF, flags)

        if b_kind == "inf":
            result = result_sign << 31
            flags["zero"] = 1
            return (result, 0xFFFFFFFF, flags)

        if b_kind == "zero":
            if a_kind == "zero":
                flags["qnan"] = 1
                return (0x7FC00001, 0x7FFFFFFF, flags)
            result = (result_sign << 31) | 0x7F800000
            flags["inf"] = 1
            flags["div_by_zero"] = 1
            return (result, 0xFFFFFFFF, flags)

        if a_kind == "zero":
            result = result_sign << 31
            flags["zero"] = 1
            return (result, 0xFFFFFFFF, flags)

        a_num, a_den = finite_fraction(opa)
        b_num, b_den = finite_fraction(opb)
        numerator = a_num * b_den
        denominator = a_den * b_num
        if denominator < 0:
            numerator = -numerator
            denominator = -denominator

    result, overflow, inexact, underflow = round_finite(
        numerator, denominator, mode
    )
    flags["overflow"] = overflow
    flags["ine"] = inexact
    flags["underflow"] = underflow
    flags["inf"] = int((result & 0x7FFFFFFF) == 0x7F800000)
    flags["zero"] = int((result & 0x7FFFFFFF) == 0)

    # Tiny finite nonzero multiply/divide outputs have specified flag exceptions.
    if op in (2, 3) and (result_sign or True):
        tiny_or_min_normal = (abs(numerator) << 126) <= denominator
        if tiny_or_min_normal:
            return (
                result,
                0,
                {
                    **flags,
                    "underflow": None,
                    "zero": None,
                },
            )

    # Inexact is unspecified for division when opa is subnormal.
    if op == 3 and classify(opa)[1] == 0 and classify(opa)[2] != 0:
        flags["ine"] = None

    return (result, 0xFFFFFFFF, flags)


async def start(dut):
    cocotb.start_soon(Clock(dut.clk, CLK_NS, "ns").start())
    dut.rmode.value = 0
    dut.fpu_op.value = 0
    dut.opa.value = 0
    dut.opb.value = 0
    await with_timeout(FallingEdge(dut.clk), 100, "ns")


def make_vectors():
    patterns = [
        0x00000000,  # +0
        0x80000000,  # -0
        0x00000001,  # minimum subnormal
        0x00000002,
        0x007FFFFF,  # maximum subnormal
        0x00800000,  # minimum normal
        0x00800001,
        0x3E800000,  # 0.25
        0x3F000000,  # 0.5
        0x3F800000,  # 1
        0x3FC00000,  # 1.5
        0x40000000,  # 2
        0x40400000,  # 3
        0x7F7FFFFF,  # maximum finite
        0xFF7FFFFF,
        0x7F800000,  # +infinity
        0xFF800000,  # -infinity
        0x7FC00000,  # quiet NaN
        0xFFC12345,
        0x7F800001,  # signaling NaN
        0xFF800123,
    ]

    vectors = []
    for op, mode, pair in product(range(4), range(4), product(patterns, patterns)):
        opa, opb = pair
        vectors.append((op, mode, opa, opb))

    rng = Random(20250308)
    for unused_index in range(700):
        opa_exp = rng.randint(70, 190)
        opb_exp = rng.randint(70, 190)
        opa = (rng.getrandbits(1) << 31) | (opa_exp << 23) | rng.getrandbits(23)
        opb = (rng.getrandbits(1) << 31) | (opb_exp << 23) | rng.getrandbits(23)
        vectors.append(
            (rng.randrange(4), rng.randrange(4), opa, opb)
        )

    # Include a range of exact and inexact subnormal add/subtract cases.
    for mode in range(4):
        for opa, opb in product(
            [0x00000001, 0x00000003, 0x007FFFFF, 0x00800000],
            [0x00000001, 0x00000002, 0x007FFFFF, 0x00800000],
        ):
            vectors.append((0, mode, opa, opb))
            vectors.append((1, mode, opa, opb))

    return vectors


def check_result(dut, expected, cycle):
    if expected is None:
        return

    expected_out, out_mask, expected_flags = expected
    actual_out = int(dut.out.value)
    assert (actual_out & out_mask) == (expected_out & out_mask), (
        f"cycle {cycle}: out got 0x{actual_out:08x}, "
        f"expected 0x{expected_out:08x} (mask 0x{out_mask:08x})"
    )

    for name in FLAG_NAMES:
        wanted = expected_flags[name]
        if wanted is None:
            continue
        actual = int(dut[name].value)
        assert actual == wanted, (
            f"cycle {cycle}: {name} got {actual}, expected {wanted}"
        )


@cocotb.test()
async def floating_point_operations(dut):
    await start(dut)
    vectors = make_vectors()
    idle = (0, 0, 0, 0)

    # Three extra inputs flush the last three operations through the pipeline.
    stream = vectors + [idle, idle, idle]
    for cycle, (op, mode, opa, opb) in enumerate(stream):
        await with_timeout(FallingEdge(dut.clk), 100, "ns")
        dut.fpu_op.value = op
        dut.rmode.value = mode
        dut.opa.value = opa
        dut.opb.value = opb

        await with_timeout(RisingEdge(dut.clk), 100, "ns")
        await Timer(1, unit="ns")

        if cycle >= 3:
            source = vectors[cycle - 3]
            expected = expected_result(*source)
            check_result(dut, expected, cycle - 3)
